/**
 * ERZEUGTE DATEI — nicht von Hand sortieren, nicht umsortieren, nichts löschen.
 * Neu erzeugen mit:  npx tsx scripts/erzeuge-korpus-anker.mts
 *
 * ── Wozu der Anker gut ist ──────────────────────────────────────────────────
 * Das No-Repeat-Ledger (ledger.ts) merkt sich je Kind in einem Bitset
 * (`TypingProgress.seenBausteine`), WELCHE Zeile es schon getippt hat — über die
 * POSITION des Bausteins im Content-Manifest. Verschiebt sich eine Position,
 * zeigt jedes gesetzte Bit auf die falsche Zeile; darum verwirft
 * `seenLedgerValid` in so einem Fall das ganze Bitset, und das Kind bekommt
 * seinen halben Vorrat noch einmal serviert.
 *
 * Bis L1 (21.08.2026) ergab sich die Reihenfolge allein aus der Quelltext-
 * Reihenfolge von `[...CORPUS, ...CORPUS_EN]`. Das ging schief, sobald eine
 * Charge DEUTSCHE Zeilen anhängte: die stehen im Quelltext VOR dem englischen
 * Block und schoben damit sämtliche englischen Indizes nach hinten. Gemessen am
 * Stand 5dec7b0 (2331 DE + 1637 EN = 3968 Bausteine): rein englischer Zuwachs
 * war unschädlich, jeder deutsche Zuwachs verwarf das Ledger.
 *
 * Diese Liste beendet das STRUKTURELL statt disziplinarisch: Sie hält die
 * kanonische Reihenfolge der Baustein-IDs fest. `manifestFor` (corpusManifest.ts)
 * baut das Manifest strikt nach dieser Liste und hängt alles, was hier NICHT
 * steht, hinten an. Wo im Quelltext eine neue Zeile landet, ist damit egal — sie
 * kommt immer hinten. Auch eine ENTFERNTE Zeile ist unschädlich: Ihre ID bleibt
 * hier als (nie servierte) Lücke stehen und hält den Platz frei.
 *
 * ── ANLEITUNG FÜR JEDE INHALTS-CHARGE (bitte wirklich lesen) ────────────────
 * Beispiel: Eine Charge legt deutsche UND englische Ziffern-Zeilen nach.
 *
 *  1. Zeilen einpflegen wie gewohnt — deutsche in eine `corpus*.ts` und in
 *     `CORPUS`, englische in eine `corpusEn*.ts` und in `CORPUS_EN`. WO im
 *     Quelltext sie landen, ist seit L1 gleichgültig; die alte Vorschrift
 *     „nur hinten anhängen" ist damit keine Bedingung mehr (schadet aber nie).
 *     Es ist auch gleichgültig, ob zuerst Deutsch oder zuerst Englisch kommt.
 *  2. ERST WENN ALLE Zeilen der Charge im Quelltext stehen — nicht nach jeder
 *     Teilwelle — genau einmal:
 *
 *         npx tsx scripts/erzeuge-korpus-anker.mts
 *
 *     Das Skript hängt die neuen IDs HINTEN an und rührt keinen bestehenden
 *     Platz an; es bricht lieber ab, als etwas zu verschieben. Mehrmals laufen
 *     lassen schadet nicht (beim zweiten Mal meldet es „0 neu"), aber die
 *     Reihenfolge der neuen Plätze ergibt sich aus dem Stand beim Lauf — darum
 *     lieber einmal am Ende als häufig zwischendurch.
 *  3. Die geänderte `corpusAnker.ts` GEHÖRT IN DENSELBEN COMMIT wie die neuen
 *     Zeilen. Getrennt committen heißt: Zwischen den beiden Commits steht ein
 *     Stand im Repo, dessen Anker nicht zum Korpus passt.
 *
 * WORAN MAN MERKT, DASS MAN ES VERGESSEN HAT: `npx vitest run` wird rot in
 * `tests/typing-ledger-anker.test.ts`, §4 („der Anker muss den ganzen lebenden
 * Korpus abdecken"), mit der Zahl der fehlenden Bausteine und genau diesem
 * Befehl in der Meldung. Zum Vorabprüfen ohne Testlauf:
 *
 *         npx tsx scripts/erzeuge-korpus-anker.mts --check
 *
 * Und was passiert, wenn man es trotzdem vergisst und deployt? Nichts
 * Schlimmes, SOFORT: Die neuen Zeilen bekommen ihre Plätze aus der
 * Quelltext-Reihenfolge und die bestehenden bleiben unberührt, das Ledger hält.
 * Gefährlich wird es erst bei der ÜBERNÄCHSTEN Charge — die könnte dann vor die
 * nicht verankerten Zeilen greifen und sie verschieben. Darum der Wächter.
 *
 * ── Format ──────────────────────────────────────────────────────────────────
 * Eine flache Liste von `bausteinId`-Strings (base36-FNV-1a über `bausteinKey`),
 * als ein Text mit Zeilenumbrüchen gespeichert — diff-freundlich: ein Zuwachs
 * erzeugt nur neue Zeilen am Ende, der Bestand bleibt Zeile für Zeile gleich.
 */

